import assert from "node:assert/strict";
import {
	Check,
	CheckAsync,
	Finish,
	Fire,
	Flip,
	Ledger,
	LinesWith,
	MakeCounter,
	Make,
	OpenStorage,
	rm,
	Validate,
	FakeStorage,
} from "../Harness.js";

/**
 * @module Test
 *
 * Exercises the wiring and the storage.
 *
 * @remarks
 *
 * Covers the loader contract (apply returns nothing), the live disabled cold mount, the root-context
 * registration with the distinct root identity, the service registered from apply, the activation
 * proof, the fail-loud validation, the absent facility (silent skip), the loud open failure, and
 * the restart recovery with the continued sequence.
 */
/**
 * A standard enabled mount with an optional storage facility attached.
 */
const Setup = (Config: Record<string, unknown> = {}, Facility: unknown = undefined): any => {
	rm();
	return Make(
		Validate({ logFile: Ledger, enabled: true, ...Config }),
		(Context: any) => {
			if (Facility !== undefined) {
				Context.storageDomain = Facility;
			}
		},
	);
};

export const runTest = async (): Promise<number> => {
	const Count = MakeCounter();

	// Group W1: the cold mount (the live disabled posture: registered, silent,
	// and the flip is live).
	{
		rm();
		const Run = Make(Validate({ logFile: Ledger, enabled: false }));
		Check(Count, "W1: apply returns NOTHING and the service is still provided", () => {
			assert.equal(Run.Returned, undefined);
			assert.ok(Run.Provided["workspaceApprove"] !== undefined);
		});
		Check(Count, "W1: a disabled mount registers EVERY surface (listener and storage effect)", () => {
			assert.deepEqual(Run.RootNames, ["fs/observed"]);
			assert.deepEqual(Run.Effects, ["approve-storage"]);
		});
		Check(Count, "W1: the cold mount logs the byte-exact disabled line", () => {
			assert.deepEqual(Run.Lines, ["approve: disabled (enabled=false)"]);
		});
		Check(Count, "W1: a disabled fs/observed event passes through with zero new lines", () => {
			const Before = Run.Lines.length;
			Fire(Run, "/repo/src/a.ts", "1");
			assert.equal(Run.Lines.length, Before);
			assert.equal(Run.State.Ring.length, 0);
		});
		Check(Count, "W1: a disabled service call refuses with zero new lines", () => {
			const Before = Run.Lines.length;
			const Service = Run.Context.workspaceApprove;
			assert.equal(
				Service.bind({ path: "/repo/a.ts", fingerprint: "fp-1", version: "1", constraints: ["no tests"] }),
				undefined,
			);
			assert.equal(Service.check({ path: "/repo/a.ts", fingerprint: "fp-1", version: "1" }), undefined);
			assert.equal(Service.approve("ap-1", "human-1"), undefined);
			assert.equal(Service.statistics().bindings, 0);
			assert.equal(Run.Lines.length, Before);
		});
	}

	// Group W1: the flip is live (the volatile cell refresh, no remount).
	{
		rm();
		const Run = Make(Validate({ logFile: Ledger, enabled: false }));
		Flip(Run.Raw.enabled, true);
		Run.CtxListeners["loader/volatile-update"](["enabled"]);
		Check(Count, "W1: a volatile flip to enabled acts on the very next call, no remount", () => {
			assert.equal(Run.State.On, true);
			const Bound = Run.Context.workspaceApprove.bind({
				path: "/repo/a.ts",
				fingerprint: "fp-1",
				version: "1",
				constraints: ["no tests"],
			});
			assert.ok(Bound !== undefined);
			assert.ok(Run.Lines.includes("approve: bound ap-1 /repo/a.ts fingerprint fp-1"));
		});
		Flip(Run.Raw.enabled, false);
		Run.CtxListeners["loader/volatile-update"](["enabled"]);
		Check(Count, "W1: the flip back to disabled silences the very next call", () => {
			const Before = Run.Lines.length;
			Fire(Run, "/repo/a.ts", "2");
			assert.equal(Run.Lines.length, Before);
			assert.equal(Run.Context.workspaceApprove.approve("ap-1", "human-1"), undefined);
		});
	}

	// Group W2: the activation wiring.
	{
		const Run = Setup();
		Check(Count, "W2: fs/observed is registered on the ROOT context only", () => {
			assert.deepEqual(Run.RootNames, ["fs/observed"]);
			assert.equal(Run.CtxListeners["fs/observed"], undefined);
		});
		Check(Count, "W2: the root identity is a distinct context object", () => {
			assert.notEqual(Run.Root, Run.Context);
			assert.equal(Object.getPrototypeOf(Run.Root), Object.prototype);
		});
		Check(Count, "W2: the activation line is byte-exact and the storage effect is armed", () => {
			assert.deepEqual(Run.Lines, ["approve: activated (domain=workspace_approve)"]);
			assert.deepEqual(Run.Effects, ["approve-storage"]);
			assert.ok(Run.State !== undefined);
		});
	}

	// Group W3: the fail-loud validation.
	{
		rm();
		Check(Count, "W3: an empty domain fails loud at load", () => {
			assert.throws(
				() => Make(Validate({ logFile: Ledger, enabled: true, domain: "" })),
				/approve: domain must be a non-empty string/,
			);
		});
		Check(Count, "W3: maxBindings below 1 fails loud at load", () => {
			assert.throws(
				() => Make(Validate({ logFile: Ledger, enabled: true, maxBindings: 0 })),
				/approve: maxBindings must be an integer >= 1/,
			);
		});
		Check(Count, "W3: a non-boolean requireConstraints fails loud at load", () => {
			assert.throws(
				() => Make(Validate({ logFile: Ledger, enabled: true, requireConstraints: "yes" })),
				/requireConstraints/,
			);
		});
	}

	// Group W4: the absent facility is a silent skip.
	{
		const Run = Setup();
		Check(Count, "W4: with no facility the effect is a silent skip and the bindings live in memory", () => {
			assert.deepEqual(Run.Effects, ["approve-storage"]);
			assert.equal(Run.State.Handle, undefined);
			assert.deepEqual(LinesWith(Run, "storage open failed"), []);
		});
	}

	// Group W5: the loud open failure.
	{
		const Run = Setup();
		const Store = FakeStorage({ failOpen: true });
		await CheckAsync(Count, "W5: a failed open logs the byte-exact line and degrades", async () => {
			await OpenStorage(Run, Store.facility);
			assert.deepEqual(LinesWith(Run, "storage open failed"), [
				"approve: storage open failed: storage unavailable",
			]);
			assert.equal(Run.State.Handle, undefined);
		});
	}

	// Group W6: the restart recovery.
	{
		const Store = FakeStorage();
		Store.seed("bindings", "ap-1", {
			id: "ap-1",
			path: "/repo/a.ts",
			fingerprint: "fp-1",
			version: "1",
			constraints: ["no tests"],
			summary: "first",
			decision: "approved",
			committedBy: "human-1",
			sequence: 1,
		});
		Store.seed("bindings", "ap-2", {
			id: "ap-2",
			path: "/repo/b.ts",
			fingerprint: "fp-2",
			version: "2",
			constraints: ["review first"],
			summary: "second",
			decision: "pending",
			sequence: 5,
		});
		Store.seed("ring", "__ring", [
			{
				id: "ap-1",
				path: "/repo/a.ts",
				fingerprint: "fp-1",
				version: "1",
				constraints: ["no tests"],
				summary: "first",
				decision: "approved",
				committedBy: "human-1",
				sequence: 1,
			},
			{
				id: "ap-2",
				path: "/repo/b.ts",
				fingerprint: "fp-2",
				version: "2",
				constraints: ["review first"],
				summary: "second",
				decision: "pending",
				sequence: 5,
			},
			{ id: "broken" },
		]);
		const Run = Setup();
		await CheckAsync(Count, "W6: the recovery rebuilds the by-id map and the ring, skipping invalid rows", async () => {
			await OpenStorage(Run, Store.facility);
			assert.equal(Run.State.ById.size, 2);
			assert.equal(Run.State.Ring.length, 2);
			assert.equal(Run.State.ById.get("ap-2").decision, "pending");
			assert.ok(Run.State.Handle !== undefined);
		});
		await CheckAsync(Count, "W6: the sequence restarts at the maximum loaded sequence, never a wall clock", async () => {
			assert.equal(Run.State.Sequence.Value, 5);
			assert.equal(Store.spec.name, "workspace_approve");
			assert.equal(Store.spec.version, 1);
			assert.ok(Store.spec.tables.bindings !== undefined);
			assert.ok(Store.spec.tables.ring !== undefined);
		});
	}

	return Finish(Count, "Wiring-And-Storage");
};

// Standalone entry: `node Target/Test/Wiring-And-Storage/Test.js`.
const InvokedDirectly =
	process.argv[1] !== undefined &&
	import.meta.url === (await import("node:url")).pathToFileURL(process.argv[1]).href;
if (InvokedDirectly) {
	const Pass = await runTest();
	console.log(`${Pass} PASS - Wiring-And-Storage`);
}
